    const width = Math.max(0, Math.floor(Number(options.width) || 0));
    const height = Math.max(0, Math.floor(Number(options.height) || 0));
    const start = { x: Math.round(Number(options.start?.x)), y: Math.round(Number(options.start?.y)) };
    const goal = { x: Math.round(Number(options.goal?.x)), y: Math.round(Number(options.goal?.y)) };
    if (!width || !height || !validPoint(start, width, height) || !validPoint(goal, width, height)) return [];

    const neighbors = Array.isArray(options.neighbors) && options.neighbors.length ? options.neighbors : CARDINAL_NEIGHBORS;
    const isWalkable = typeof options.isWalkable === "function" ? options.isWalkable : () => true;
    const movementCost = typeof options.movementCost === "function" ? options.movementCost : () => 1;
    const heuristic = typeof options.heuristic === "function"
      ? options.heuristic
      : (x, y, goalX, goalY) => Math.abs(goalX - x) + Math.abs(goalY - y);
    const isGoal = typeof options.isGoal === "function"
      ? options.isGoal
      : (x, y, destination) => x === destination.x && y === destination.y;
    const preventCornerCutting = options.preventCornerCutting === true;
    const distanceBudget = Math.abs(goal.x - start.x) + Math.abs(goal.y - start.y);
    const defaultBudget = Math.min(Math.max(1, distanceBudget * 80), width * height, 150000);
    const maxIterations = Math.max(1, Math.floor(Number(options.maxIterations) || defaultBudget));

