      const current = open.pop();
      const currentIndex = buffers.index(current.y, current.x);
      if (buffers.closedStamp[currentIndex] === generation || current.g !== buffers.getG(current.y, current.x)) continue;
      iterations += 1;
      if (isGoal(current.x, current.y, goal)) return rebuildPath(start, current);
      buffers.closedStamp[currentIndex] = generation;

